<?php
namespace App\Domain\Capabilities; use App\Domain\Homepage\HomepageCache; use App\Domain\Industries\IndustryCache; use App\Domain\PublicChrome\PublicChromeCache; use App\Models\{HomepageItem,IndustryNeed,NavigationItem}; use Illuminate\Support\Facades\Cache; use Throwable; final class CapabilityCache { public static function version(int $id):int{try{return (int)Cache::rememberForever("public.capabilities.version.$id",fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function indexVersion():int{try{return (int)Cache::rememberForever('public.capabilities.index.version',fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function forget(int $id):void{try{Cache::put("public.capabilities.version.$id",hrtime(true));Cache::put('public.capabilities.index.version',hrtime(true));if(HomepageItem::where('capability_id',$id)->exists())HomepageCache::forget();if(NavigationItem::where('capability_id',$id)->exists())PublicChromeCache::forgetAll();IndustryNeed::where('capability_id',$id)->pluck('industry_id')->each(fn($industryId)=>IndustryCache::forget((int)$industryId));}catch(Throwable){}} }
